<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>2048</title>
<style>
  :root {
    --bg: #1a1a2e;
    --board-bg: #16213e;
    --cell-bg: #0f3460;
    --text: #e94560;
    --text-light: #f5f5f5;
    --tile-2: #2ec4b6;
    --tile-4: #3a86ff;
    --tile-8: #8338ec;
    --tile-16: #ff006e;
    --tile-32: #fb5607;
    --tile-64: #ffbe0b;
    --tile-128: #06d6a0;
    --tile-256: #118ab2;
    --tile-512: #ef476f;
    --tile-1024: #073b4c;
    --tile-2048: #ffd166;
    --tile-super: #000000;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body {
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
    background: var(--bg);
    color: var(--text-light);
    min-height: 100vh;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    padding: 20px;
  }
  h1 {
    font-size: 3rem;
    margin-bottom: 10px;
    background: linear-gradient(90deg, #e94560, #f5f5f5);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
  }
  .game-info {
    display: flex;
    gap: 20px;
    align-items: center;
    margin-bottom: 20px;
  }
  #score {
    background: var(--board-bg);
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 1.2rem;
    font-weight: bold;
    min-width: 150px;
    text-align: center;
    border: 2px solid var(--text);
  }
  #score .label {
    font-size: 0.8rem;
    color: #aaa;
    display: block;
  }
  #reset {
    background: var(--text);
    color: var(--text-light);
    border: none;
    padding: 10px 20px;
    border-radius: 8px;
    font-size: 1rem;
    font-weight: bold;
    cursor: pointer;
    transition: transform 0.1s, opacity 0.2s;
  }
  #reset:hover { opacity: 0.9; }
  #reset:active { transform: scale(0.95); }
  #board {
    background: var(--board-bg);
    padding: 10px;
    border-radius: 10px;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    grid-template-rows: repeat(4, 1fr);
    gap: 10px;
    width: 400px;
    height: 400px;
  }
  .cell {
    background: var(--cell-bg);
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 1.5rem;
    font-weight: bold;
    color: var(--text-light);
    transition: background-color 0.2s;
  }
  .cell[data-value="2"]    { background: var(--tile-2); }
  .cell[data-value="4"]    { background: var(--tile-4); }
  .cell[data-value="8"]    { background: var(--tile-8); }
  .cell[data-value="16"]   { background: var(--tile-16); }
  .cell[data-value="32"]   { background: var(--tile-32); }
  .cell[data-value="64"]   { background: var(--tile-64); color: #000; }
  .cell[data-value="128"]  { background: var(--tile-128); font-size: 1.3rem; }
  .cell[data-value="256"]  { background: var(--tile-256); font-size: 1.3rem; }
  .cell[data-value="512"]  { background: var(--tile-512); font-size: 1.3rem; }
  .cell[data-value="1024"] { background: var(--tile-1024); font-size: 1.1rem; }
  .cell[data-value="2048"] { background: var(--tile-2048); color: #000; font-size: 1.1rem; }
  .cell[data-value="4096"], .cell[data-value="8192"], .cell[data-value="16384"] {
    background: var(--tile-super);
    font-size: 1rem;
  }
  .empty { background: var(--cell-bg); }
  .hint {
    margin-top: 20px;
    color: #888;
    font-size: 0.9rem;
    text-align: center;
  }
</style>
</head>
<body>
  <h1>2048</h1>
  <div class="game-info">
    <div id="score"><span class="label">SCORE</span>0</div>
    <button id="reset">New Game</button>
  </div>
  <div id="board"></div>
  <p class="hint">Use arrow keys to move tiles. Tiles with the same number merge into one!</p>

<script>
(function () {
  const SIZE = 4;
  const boardEl = document.getElementById('board');
  const scoreEl = document.getElementById('score');
  const resetEl = document.getElementById('reset');

  // Internal state. Use a fresh grid object reference each mutation so equality
  // checks (board changed?) work reliably.
  let grid = [];
  let currentScore = 0;

  function emptyGrid() {
    const g = new Array(SIZE);
    for (let i = 0; i < SIZE; i++) {
      g[i] = new Array(SIZE).fill(0);
    }
    return g;
  }

  function cloneGrid(g) {
    const out = new Array(SIZE);
    for (let i = 0; i < SIZE; i++) {
      out[i] = g[i].slice();
    }
    return out;
  }

  function gridsEqual(a, b) {
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        if (a[i][j] !== b[i][j]) return false;
      }
    }
    return true;
  }

  function emptyCells(g) {
    const cells = [];
    for (let i = 0; i < SIZE; i++) {
      for (let j = 0; j < SIZE; j++) {
        if (g[i][j] === 0) cells.push([i, j]);
      }
    }
    return cells;
  }

  function spawnTile(g) {
    const empties = emptyCells(g);
    if (empties.length === 0) return;
    const idx = Math.floor(Math.random() * empties.length);
    const [r, c] = empties[idx];
    g[r][c] = Math.random() < 0.9 ? 2 : 4;
  }

  // Slide a single row (length SIZE) left, returning { row, gained }.
  // gained = total score added by merges performed on this row.
  function slideRowLeft(row) {
    const n = row.length;
    const filtered = [];
    for (let i = 0; i < n; i++) {
      if (row[i] !== 0) filtered.push(row[i]);
    }
    const merged = [];
    let gained = 0;
    let i = 0;
    while (i < filtered.length) {
      if (i + 1 < filtered.length && filtered[i] === filtered[i + 1]) {
        const v = filtered[i] * 2;
        merged.push(v);
        gained += v;
        i += 2;
      } else {
        merged.push(filtered[i]);
        i += 1;
      }
    }
    while (merged.length < n) merged.push(0);
    return { row: merged, gained: gained };
  }

  // Apply a move given a function that pulls (r,c) -> value, and pushes value back.
  // direction = 'left' | 'right' | 'up' | 'down'.
  function applyMove(direction) {
    const before = cloneGrid(grid);
    let totalGained = 0;

    if (direction === 'left') {
      for (let r = 0; r < SIZE; r++) {
        const res = slideRowLeft(before[r]);
        before[r] = res.row;
        totalGained += res.gained;
      }
    } else if (direction === 'right') {
      for (let r = 0; r < SIZE; r++) {
        const reversed = before[r].slice().reverse();
        const res = slideRowLeft(reversed);
        before[r] = res.row.reverse();
        totalGained += res.gained;
      }
    } else if (direction === 'up') {
      for (let c = 0; c < SIZE; c++) {
        const col = [];
        for (let r = 0; r < SIZE; r++) col.push(before[r][c]);
        const res = slideRowLeft(col);
        totalGained += res.gained;
        for (let r = 0; r < SIZE; r++) before[r][c] = res.row[r];
      }
    } else if (direction === 'down') {
      for (let c = 0; c < SIZE; c++) {
        const col = [];
        for (let r = SIZE - 1; r >= 0; r--) col.push(before[r][c]);
        const res = slideRowLeft(col);
        totalGained += res.gained;
        for (let r = 0; r < SIZE; r++) before[r][c] = res.row[SIZE - 1 - r];
      }
    } else {
      return false;
    }

    if (!gridsEqual(before, grid)) {
      grid = before;
      currentScore += totalGained;
      spawnTile(grid);
      render();
      return true;
    }
    return false;
  }

  function render() {
    boardEl.innerHTML = '';
    for (let r = 0; r < SIZE; r++) {
      for (let c = 0; c < SIZE; c++) {
        const v = grid[r][c];
        const cell = document.createElement('div');
        if (v === 0) {
          cell.className = 'cell empty';
          cell.textContent = '';
        } else {
          cell.className = 'cell';
          cell.setAttribute('data-value', String(v));
          cell.textContent = String(v);
        }
        boardEl.appendChild(cell);
      }
    }
    scoreEl.innerHTML = '<span class="label">SCORE</span>' + currentScore;
  }

  function resetGame() {
    grid = emptyGrid();
    currentScore = 0;
    spawnTile(grid);
    spawnTile(grid);
    render();
  }

  // Public API on window.game
  window.game = {
    size: SIZE,
    reset: function () { resetGame(); },
    move: function (direction) { return applyMove(direction); },
    board: function () { return cloneGrid(grid); },
    setBoard: function (arr) {
      if (!arr || arr.length !== SIZE) return;
      const next = emptyGrid();
      for (let r = 0; r < SIZE; r++) {
        if (!arr[r] || arr[r].length !== SIZE) return;
        for (let c = 0; c < SIZE; c++) {
          const v = arr[r][c] | 0;
          next[r][c] = v;
        }
      }
      grid = next;
      // setBoard does not change the score and does not spawn a tile.
      render();
    },
    score: function () { return currentScore; }
  };

  // Wire up keyboard controls.
  window.addEventListener('keydown', function (ev) {
    const map = {
      ArrowLeft: 'left',
      ArrowRight: 'right',
      ArrowUp: 'up',
      ArrowDown: 'down'
    };
    if (map[ev.key]) {
      ev.preventDefault();
      applyMove(map[ev.key]);
    }
  });

  resetEl.addEventListener('click', function () { resetGame(); });

  // Initial render.
  resetGame();
})();
</script>
</body>
</html>
